head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gIDX_MKT_CLSS_ID = "";
scwin.gIDX_ASST_CLSS_ID = "";
scwin.gIDX_MKT_CLSS_ID_L = "";
scwin.gIDX_MKT_CLSS_ID_M = "";
scwin.gIDX_ASST_CLSS_ID_L = "";
scwin.gIDX_ASST_CLSS_ID_M = "";
// 세션정보를 얻기위한 함수사용
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd"); // 오늘날짜

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
        $c.cm.PanelToGroupBox(panel_Top);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24600.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    edt_Date.setValue(scwin.vCurDate);
    await scwin.searchCode();
    await scwin.searchCombo();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cmb_MKT_TP_CD_L_onselchange
 * @description cmb_MKT_TP_CD_L onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_MKT_TP_CD_L_onselchange = function() {
    try {
        scwin.gIDX_MKT_CLSS_ID_L = dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID");
        dts_MKT_TP_CD_M.UseFilter = true;
        dts_MKT_TP_CD_M.Filter();
        dts_MKT_TP_CD_M.sort("IDX_MKT_CLSS_ID", 0);
        // dts_MKT_TP_CD_M.sort(); // W-Craft 주석처리
        if (dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") === "") {
            cmb_MKT_TP_CD_M.setSelectedIndex(0);
            cmb_MKT_TP_CD_S.setSelectedIndex(0);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24600.cmb_MKT_TP_CD_L_onselchange" });
    }
};

/**
 * @method
 * @name dts_MKT_TP_CD_M_OnFilter
 * @description MKT TP CD M On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_MKT_TP_CD_M_OnFilter = function(row) {
    try {
        if (scwin.gIDX_MKT_CLSS_ID_L === "") {
            return true;
        } else {
            if (dts_MKT_TP_CD_M.getCellData(row, "UP_MKT_CLSS_ID") === scwin.gIDX_MKT_CLSS_ID_L || dts_MKT_TP_CD_M.getCellData(row, "IDX_MKT_CLSS_ID") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24600.dts_MKT_TP_CD_M_OnFilter" });
    }
};

/**
 * @method
 * @name cmb_MKT_TP_CD_M_onselchange
 * @description cmb_MKT_TP_CD_M onselchange 이벤트
