/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if ((dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") === "") && (dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID") === "") &&
            (dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID") !== "")) {
            await $c.win.alert("기초시장 대분류부터 먼저 선택해주세요!");
            return;
        } else if ((dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") === "") && (dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID") !== "") &&
            (dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID") === "")) {
            await $c.win.alert("기초시장 대분류부터 먼저 선택해주세요!");
            return;
        } else if ((dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") === "") && (dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID") !== "") &&
            (dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID") !== "")) {
            await $c.win.alert("기초시장 대분류부터 먼저 선택해주세요!");
            return;
        } else if ((dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") !== "") && (dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID") === "") &&
            (dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID") !== "")) {
            await $c.win.alert("기초시장 중분류부터 먼저 선택해주세요!");
            return;
        } else if ((dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") === "") && (dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID") === "") &&
            (dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID") !== "")) {
            await $c.win.alert("기초시장 대분류부터 먼저 선택해주세요!");
            return;
        }
        if ((dts_ULY_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") === "") && (dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") === "") &&
            (dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID") !== "")) {
            await $c.win.alert("기초자산 대분류부터 먼저 선택해주세요!");
            return;
        } else if ((dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") === "") && (dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") !== "") &&
            (dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID") === "")) {
            await $c.win.alert("기초자산 대분류부터 먼저 선택해주세요!");
            return;
        } else if ((dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") === "") && (dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") !== "") &&
            (dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID") !== "")) {
            await $c.win.alert("기초자산 대분류부터 먼저 선택해주세요!");
            return;
        } else if ((dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") !== "") && (dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") === "") &&
            (dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID") !== "")) {
            await $c.win.alert("기초자산 중분류부터 먼저 선택해주세요!");
            return;
        } else if ((dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") === "") && (dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") === "") &&
            (dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID") !== "")) {
            await $c.win.alert("기초자산 대분류부터 먼저 선택해주세요!");
            return;
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24600.btn_Search_onclick" });
    }
};

/**
