///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    03905  지수산출기관코드
    03902  지수레버리지인버스구분코드
     */
    const arrCid = [{
        cid: "IDX_CALC_INST_CD",
        cnm: "cmb_IDX_CALC_INST_CD"
    }, {
        cid: "IDX_LVRG_INVRS_TP_CD",
        cnm: "cmb_IDX_LVRG_INVRS_TP_CD"
    }];
    let objCod;
    url += "&CD_ID_M='IDX_CALC_INST_CD','IDX_LVRG_INVRS_TP_CD'";
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        // alert('[objCod]'+objCod);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^전체";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name searchCombo
 * @description 기초시장 및 기초 자산
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCombo = async function() {
    /* 기초시장 대분류 */
    url += "&method=listGeneral&outputMessageId=ETF_ETN_MKT_TP_CD_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstsrch.mkt.tp.cd.L.select.list.condition";
    const sbmOptions = {
        id : "sbm_dts_MKT_TP_CD_L",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_MKT_TP_CD_L=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_MKT_TP_CD_L.insertRow(0);
    dts_MKT_TP_CD_L.setCellData(1, "IDX_MKT_CLSS_ID", "");
    dts_MKT_TP_CD_L.setCellData(1, "IDX_MKT_CLSS_NM", "전체");
    cmb_MKT_TP_CD_L.setSelectedIndex(0);

    /* 기초시장 중분류 */
    url += "&method=listGeneral&outputMessageId=ETF_ETN_MKT_TP_CD_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstsrch.mkt.tp.cd.M.select.list.condition";
    const sbmOptions2 = {
        id : "sbm_dts_MKT_TP_CD_M",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_MKT_TP_CD_M=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_MKT_TP_CD_M.insertRow(0);
