/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        $c.stf.doLogSave("ULDSTF24600.xml", SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "유형분류 및 ETF·ETN 지수 관리", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
